def _segments(text,spans):
    out=[]
    for s in spans:
        if isinstance(s,str): out.append(s)
        elif isinstance(s,dict):
            if "text" in s: out.append(str(s.get("text","")))
            else:
                a=int(s.get("start",s.get("begin",0))); b=int(s.get("end",s.get("stop",a)))
                out.append(text[a:b])
        elif isinstance(s,(list,tuple)) and len(s)>=2: out.append(text[int(s[0]):int(s[1])])
        else: out.append("")
    return out

def _has(s,words):
    return any(w in s for w in words)

def _item(s):
    q=s.strip()
    return q.startswith(("(","•","-")) or (len(q)>1 and q[0].isalnum() and q[1] in (".",")"))

def _back(out,xs,i,words,n=3):
    for j in reversed(range(max(0,i-n),i)):
        if _has(xs[j],words):
            out.add(j); return j
    return -1

def _defhead(xs,i,n=24):
    words=("confidential information means","confidential information shall mean","proprietary information means","proprietary information shall mean","evaluation material means","information is defined as","protectable interests means")
    for j in reversed(range(max(0,i-n),i+1)):
        if _has(xs[j],words): return j
    return -1

def _definition(out,xs,i):
    j=_defhead(xs,i)
    if j>=0:
        out.add(j)
        z=j+1
        while z<len(xs) and _item(xs[z]):
            out.add(z); z+=1

def _exception(out,xs,i):
    words=("shall not include","does not include","will not include","shall exclude","shall not apply","restrictions shall not apply","obligations shall not apply","does not extend to","inoperative as to","exceptions from confidential")
    _back(out,xs,i,words,14)

